     1	package sk.knizat.tennisclub.service.impl;
     2	
     3	import lombok.RequiredArgsConstructor;
     4	import org.springframework.stereotype.Service;
     5	import org.springframework.transaction.annotation.Transactional;
     6	import sk.knizat.tennisclub.dao.CourtDao;
     7	import sk.knizat.tennisclub.dao.ReservationDao;
     8	import sk.knizat.tennisclub.dao.SurfaceTypeDao;
     9	import sk.knizat.tennisclub.dto.court.CourtRequest;
    10	import sk.knizat.tennisclub.dto.court.CourtResponse;
    11	import sk.knizat.tennisclub.entity.Court;
    12	import sk.knizat.tennisclub.entity.SurfaceType;
    13	import sk.knizat.tennisclub.exception.ConflictException;
    14	import sk.knizat.tennisclub.exception.NotFoundException;
    15	import sk.knizat.tennisclub.exception.ValidationException;
    16	import sk.knizat.tennisclub.mapper.CourtMapper;
    17	import sk.knizat.tennisclub.service.CourtService;
    18	
    19	import java.time.Clock;
    20	import java.util.List;
    21	
    22	/** Default {@link CourtService} backed by {@link CourtDao}. */
    23	@Service
    24	@Transactional
    25	@RequiredArgsConstructor
    26	public class CourtServiceImpl implements CourtService {
    27	
    28	    private static final String ENTITY = "Court";
    29	
    30	    private final CourtDao courtDao;
    31	    private final SurfaceTypeDao surfaceTypeDao;
    32	    private final ReservationDao reservationDao;
    33	    private final CourtMapper mapper;
    34	    private final Clock clock;
    35	
    36	    @Override
    37	    @Transactional(readOnly = true)
    38	    public List<CourtResponse> findAll() {
    39	        return courtDao.findAll().stream().map(mapper::toResponse).toList();
    40	    }
    41	
    42	    @Override
    43	    @Transactional(readOnly = true)
    44	    public CourtResponse findById(Long id) {
    45	        return mapper.toResponse(getOrThrow(id));
    46	    }
    47	
    48	    @Override
    49	    public CourtResponse create(CourtRequest request) {
    50	        if (courtDao.existsByCourtNumber(request.courtNumber())) {
    51	            throw duplicateNumber(request.courtNumber());
    52	        }
    53	        SurfaceType surfaceType = resolveSurfaceType(request.surfaceTypeId());
    54	        Court saved = courtDao.save(mapper.toEntity(request, surfaceType));
    55	        return mapper.toResponse(saved);
    56	    }
    57	
    58	    @Override
    59	    public CourtResponse update(Long id, CourtRequest request) {
    60	        Court entity = getOrThrow(id);
    61	        boolean takenByOther = courtDao.findByCourtNumber(request.courtNumber())
    62	                .map(other -> !other.getId().equals(id))
    63	                .orElse(false);
    64	        if (takenByOther) {
    65	            throw duplicateNumber(request.courtNumber());
    66	        }
    67	        SurfaceType surfaceType = resolveSurfaceType(request.surfaceTypeId());
    68	        mapper.updateEntity(entity, request, surfaceType);
    69	        return mapper.toResponse(courtDao.save(entity));
    70	    }
    71	
    72	    @Override
    73	    public void delete(Long id) {
    74	        Court entity = getOrThrow(id);
    75	        if (reservationDao.existsUnfinishedByCourt(id, clock.instant())) {
    76	            throw new ConflictException(
    77	                    "Court with id " + id + " has unfinished reservations and cannot be deleted");
    78	        }
    79	        courtDao.softDelete(entity, clock.instant());
    80	    }
    81	
    82	    private Court getOrThrow(Long id) {
    83	        return courtDao.findById(id).orElseThrow(() -> NotFoundException.of(ENTITY, id));
    84	    }
    85	
    86	    /** The surface type id comes from the payload, so an unknown or deleted one is a 400, not a 404. */
    87	    private SurfaceType resolveSurfaceType(Long surfaceTypeId) {
    88	        return surfaceTypeDao.findById(surfaceTypeId)
    89	                .orElseThrow(() -> new ValidationException("surfaceTypeId " + surfaceTypeId + " does not exist"));
    90	    }
    91	
    92	    private static ConflictException duplicateNumber(Integer courtNumber) {
    93	        return new ConflictException("Court with number " + courtNumber + " already exists");
    94	    }
    95	}

