   131	 * @param <T> entity type
   132	 */
   133	public interface GenericDao<T extends BaseEntity> {
   134	
   135	    /**
   136	     * Finds a non-deleted entity by id.
   137	     *
   138	     * @return the entity, or empty when it does not exist or is soft-deleted
   139	     */
   140	    Optional<T> findById(Long id);
   141	
   142	    /** Returns all non-deleted entities ordered by id. */
   143	    List<T> findAll();
   144	
   145	    /**
   146	     * Persists a new entity ({@code id == null}) or merges a detached/updated one.
   147	     * <p>
   148	     * Updates must follow load-then-modify: load the managed entity via {@link #findById(Long)}, change it and
   149	     * pass it here. Never build a fresh object with an id and merge it: merge copies every field, so
   150	     * {@code createdAt} would be lost on the returned instance and a soft-deleted row would be silently revived.
