   156	     */
   157	    T save(T entity);
   158	
   159	    /**
   160	     * Soft-deletes the entity: marks it deleted at {@code now} and merges the change.
   161	     * Idempotent for an already deleted entity. Flushed before returning.
   162	     *
   163	     * @param now deletion time supplied by the caller from the application {@code Clock}
   164	     */
   165	    void softDelete(T entity, Instant now);
   166	
   167	    /** Tells whether a non-deleted entity with the given id exists. */
   168	    boolean existsById(Long id);
