    27	/**
    28	 * Maps exceptions to RFC 7807 {@link ProblemDetail} responses ({@code application/problem+json}).
    29	 * <p>
    30	 * Extends {@link ResponseEntityExceptionHandler}, so every standard Spring MVC exception (405, 406, 415,
    31	 * unknown path 404, ...) is a problem detail as well. Validation problems carry an extra {@code errors}
    32	 * property (field or parameter name to message). 401/403 are produced by the security entry points (step 7).
    33	 */
    34	@RestControllerAdvice
    35	@Slf4j
    36	public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {
    37	
    38	    private static final String ERRORS = "errors";
    39	    private static final String VALIDATION_TITLE = "Validation failed";
    40	    private static final String FALLBACK_MESSAGE = "invalid value";
    41	
    42	    @Override
    43	    protected ResponseEntity<Object> handleMethodArgumentNotValid(MethodArgumentNotValidException ex,
    44	                                                                  HttpHeaders headers, HttpStatusCode status,
    45	                                                                  WebRequest request) {
    46	        Map<String, String> errors = new TreeMap<>();
    47	        ex.getBindingResult().getFieldErrors().forEach(
    48	                error -> errors.putIfAbsent(error.getField(), messageOf(error)));
    49	        return handleExceptionInternal(ex, validationProblem(errors), headers, status, request);
    50	    }
    51	
    52	    @Override
    53	    protected ResponseEntity<Object> handleHandlerMethodValidationException(HandlerMethodValidationException ex,
    54	                                                                            HttpHeaders headers,
    55	                                                                            HttpStatusCode status,
    56	                                                                            WebRequest request) {
    57	        Map<String, String> errors = new TreeMap<>();
    58	        ex.getParameterValidationResults().forEach(result -> {
    59	            String name = result.getMethodParameter().getParameterName();
    60	            result.getResolvableErrors().forEach(
    61	                    error -> errors.putIfAbsent(name == null ? FALLBACK_MESSAGE : name, messageOf(error)));
    62	        });
    63	        return handleExceptionInternal(ex, validationProblem(errors), headers, status, request);
    64	    }
    65	
    66	    @Override
    67	    protected ResponseEntity<Object> handleHttpMessageNotReadable(HttpMessageNotReadableException ex,
    68	                                                                  HttpHeaders headers, HttpStatusCode status,
    69	                                                                  WebRequest request) {
    70	        ProblemDetail problem = problem(HttpStatus.BAD_REQUEST, "Malformed request",
    71	                "Request body is missing or malformed");
    72	        return handleExceptionInternal(ex, problem, headers, status, request);
    73	    }
    74	
    75	    @Override
    76	    protected ResponseEntity<Object> handleMissingServletRequestParameter(MissingServletRequestParameterException ex,
    77	                                                                          HttpHeaders headers,
    78	                                                                          HttpStatusCode status,
    79	                                                                          WebRequest request) {
    80	        ProblemDetail problem = problem(HttpStatus.BAD_REQUEST, "Missing parameter",
    81	                "Required parameter '" + ex.getParameterName() + "' is missing");
    82	        return handleExceptionInternal(ex, problem, headers, status, request);
    83	    }
    84	
    85	    @ExceptionHandler(MethodArgumentTypeMismatchException.class)
    86	    public ProblemDetail handleTypeMismatch(MethodArgumentTypeMismatchException ex) {
    87	        String type = ex.getRequiredType() == null ? "a different type" : ex.getRequiredType().getSimpleName();
    88	        return problem(HttpStatus.BAD_REQUEST, "Invalid parameter",
    89	                "Parameter '" + ex.getName() + "' must be of type " + type);
    90	    }
    91	
    92	    @ExceptionHandler(ValidationException.class)
    93	    public ProblemDetail handleValidation(ValidationException ex) {
    94	        return problem(HttpStatus.BAD_REQUEST, VALIDATION_TITLE, ex.getMessage());
    95	    }
    96	
    97	    @ExceptionHandler(NotFoundException.class)
    98	    public ProblemDetail handleNotFound(NotFoundException ex) {
    99	        return problem(HttpStatus.NOT_FOUND, "Not found", ex.getMessage());
   100	    }
   101	
   102	    @ExceptionHandler(ConflictException.class)
   103	    public ProblemDetail handleConflict(ConflictException ex) {
   104	        return problem(HttpStatus.CONFLICT, "Conflict", ex.getMessage());
   105	    }
   106	
   107	    /** Last resort: unexpected failures become a generic 500 problem without leaking internals. */
   108	    @ExceptionHandler(Exception.class)
   109	    public ProblemDetail handleUnexpected(Exception ex) {
   110	        log.error("Unhandled exception", ex);
   111	        return problem(HttpStatus.INTERNAL_SERVER_ERROR, "Internal server error", "An unexpected error occurred");
   112	    }
   113	
   114	    private static ProblemDetail validationProblem(Map<String, String> errors) {
   115	        ProblemDetail problem = problem(HttpStatus.BAD_REQUEST, VALIDATION_TITLE, "Request validation failed");
   116	        problem.setProperty(ERRORS, errors);
   117	        return problem;
   118	    }
   119	
   120	    private static ProblemDetail problem(HttpStatus status, String title, String detail) {
   121	        log.debug("Responding {} {}: {}", status.value(), title, detail);
   122	        ProblemDetail problem = ProblemDetail.forStatusAndDetail(status, detail);
   123	        problem.setTitle(title);
   124	        return problem;
   125	    }
   126	
   127	    private static String messageOf(MessageSourceResolvable error) {
   128	        return error.getDefaultMessage() == null ? FALLBACK_MESSAGE : error.getDefaultMessage();
   129	    }
   130	}
